    case 0x49: cyc += 4;  break;
    case 0x4A: cyc += 4; bc = (uint16_t)((bc & 0xFF00) | (uint8_t)((uint8_t)(de >> 8))); break;
    case 0x4B: cyc += 4; bc = (uint16_t)((bc & 0xFF00) | (uint8_t)((uint8_t)de)); break;
    case 0x4C: cyc += 4; bc = (uint16_t)((bc & 0xFF00) | (uint8_t)((uint8_t)(hl >> 8))); break;
    case 0x4D: cyc += 4; bc = (uint16_t)((bc & 0xFF00) | (uint8_t)((uint8_t)hl)); break;
