    case 0x55: cyc += 4; de = (uint16_t)((de & 0x00FF) | (uint8_t)((uint8_t)hl) << 8); break;
    case 0x56: cyc += 7; de = (uint16_t)((de & 0x00FF) | (uint8_t)(RD(hl)) << 8); break;
    case 0x57: cyc += 4; de = (uint16_t)((de & 0x00FF) | (uint8_t)(a) << 8); break;
