    case 0x59: cyc += 4; de = (uint16_t)((de & 0xFF00) | (uint8_t)((uint8_t)bc)); break;
    case 0x5A: cyc += 4; de = (uint16_t)((de & 0xFF00) | (uint8_t)((uint8_t)(de >> 8))); break;
    case 0x5B: cyc += 4;  break;
    case 0x5C: cyc += 4; de = (uint16_t)((de & 0xFF00) | (uint8_t)((uint8_t)(hl >> 8))); break;
    case 0x5D: cyc += 4; de = (uint16_t)((de & 0xFF00) | (uint8_t)((uint8_t)hl)); break;
    case 0x5E: cyc += 7; de = (uint16_t)((de & 0xFF00) | (uint8_t)(RD(hl))); break;
    case 0x5F: cyc += 4; de = (uint16_t)((de & 0xFF00) | (uint8_t)(a)); break;
    case 0x60: cyc += 4; hl = (uint16_t)((hl & 0x00FF) | (uint8_t)((uint8_t)(bc >> 8)) << 8); break;
    case 0x61: cyc += 4; hl = (uint16_t)((hl & 0x00FF) | (uint8_t)((uint8_t)bc) << 8); break;
    case 0x62: cyc += 4; hl = (uint16_t)((hl & 0x00FF) | (uint8_t)((uint8_t)(de >> 8)) << 8); break;
