    case 0x65: cyc += 4; hl = (uint16_t)((hl & 0x00FF) | (uint8_t)((uint8_t)hl) << 8); break;
    case 0x66: cyc += 7; hl = (uint16_t)((hl & 0x00FF) | (uint8_t)(RD(hl)) << 8); break;
    case 0x67: cyc += 4; hl = (uint16_t)((hl & 0x00FF) | (uint8_t)(a) << 8); break;
    case 0x68: cyc += 4; hl = (uint16_t)((hl & 0xFF00) | (uint8_t)((uint8_t)(bc >> 8))); break;
